import sys

data = sys.stdin.read().split()
n0 = int(data[0])
if n0 < 2:
    print(0)
else:
    s = bytearray(n0 + 1)
    cnt = 0
    for i in range(2, n0 + 1):
        if not s[i]:
            cnt += 1
            for j in range(i * i, n0 + 1, i):
                s[j] = 1
    print(cnt)

